          setStatus(result.liveReconfigured ? "RisuAI 기본 Persona는 그대로 두고, 현재 채팅을 새 Source의 Live Persona로 다시 연결했습니다." : "RisuAI 기본 Persona는 그대로 두고 현재 채팅에만 Persona를 동적 바인딩했습니다.", "ok");
